#!/usr/bin/env python3
"""Complete scoped TargetStrafe Simplified and Traditional display resource update."""
from pathlib import Path
import argparse,json
from display_locale_schema import put_module
HERE=Path(__file__).resolve().parent
PREFIX='liquidbounce.module.targetStrafe'
LABELS=json.loads(r'''{"Mode":["模式","模式"],"Motion":["移动向量","移動向量"],"Input":["方向输入","方向輸入"],"Hypixel":["Hypixel 兼容","Hypixel 相容"],"Range":["环绕范围","環繞範圍"],"Target":["目标选择","目標選擇"],"FOV":["视角范围","視角範圍"],"HurtTime":["受伤时间","受傷時間"],"Priority":["目标优先级","目標優先順序"],"Type":["实体类型","實體類型"],"Health":["生命值","生命值"],"Distance":["距离","距離"],"Direction":["准星方向","準星方向"],"Age":["存在时间","存在時間"],"FollowRange":["跟随范围","跟隨範圍"],"VerticalRange":["垂直范围","垂直範圍"],"Requirements":["启用条件","啟用條件"],"Space":["按住跳跃","按住跳躍"],"Speed":["启用加速","啟用加速"],"KillAura":["启用杀戮光环","啟用殺戮光環"],"Ground":["处于地面","處於地面"],"Planner":["路径规划","路徑規劃"],"Enabled":["启用","啟用"],"ControlDirection":["手动控制方向","手動控制方向"],"Validation":["安全校验","安全驗證"],"EdgeCheck":["边缘检查","邊緣檢查"],"MaxFallHeight":["最大下落高度","最大下落高度"],"VoidCheck":["虚空检查","虛空檢查"],"SafetyExpand":["安全扩展","安全擴展"],"AdaptiveRange":["自适应范围","自適應範圍"],"MaxRange":["最大范围","最大範圍"],"RangeStep":["范围步长","範圍步長"],"Visibility":["视线规划","視線規劃"],"SearchDistance":["探测距离","探測距離"],"Visuals":["环绕显示","環繞顯示"],"Width":["圆环宽度","圓環寬度"],"HeightOffset":["高度偏移","高度偏移"],"OuterColor":["外缘颜色","外緣顏色"],"InnerColor":["内缘颜色","內緣顏色"],"OutlineColor":["轮廓颜色","輪廓顏色"],"ShowNextPoint":["显示下一位置","顯示下一位置"],"PointRadius":["位置标记半径","位置標記半徑"],"PointColor":["安全位置颜色","安全位置顏色"],"PointOutlineColor":["安全位置轮廓","安全位置輪廓"],"InvalidPointColor":["危险位置颜色","危險位置顏色"],"InvalidPointOutlineColor":["危险位置轮廓","危險位置輪廓"]}''')
TEXTS=json.loads(r'''[["","Orbit a selected combat target with planned movement.","围绕选中的战斗目标规划移动。","圍繞選取的戰鬥目標規劃移動。"],["Mode","Rewrite motion or directional movement input.","选择改写移动向量或方向输入。","選擇改寫移動向量或方向輸入。"],["Mode.Motion","Keep horizontal speed and turn its direction around the target.","保持水平速度，并调整方向环绕目标。","保持水平速度，並調整方向環繞目標。"],["Mode.Input","Steer with discrete movement keys relative to the current view.","根据当前视角，使用离散方向按键环绕目标。","依目前視角，使用離散方向按鍵環繞目標。"],["Mode.Motion.Hypixel","Use the shared Speed Hypixel strafe phase and its minimum speed.","使用 Speed 的 Hypixel 侧移阶段及最低速度。","使用 Speed 的 Hypixel 側移階段及最低速度。"],["Range","Radius of the target range sphere; height differences reduce the orbit radius.","目标范围球的半径；高度差会减小水平环绕半径。","目標範圍球的半徑；高度差會縮小水平環繞半徑。"],["Target","Select a target when KillAura and Aimbot have no locked target.","杀戮光环和辅助瞄准没有锁定目标时，按此设置选择目标。","殺戮光環和輔助瞄準未鎖定目標時，依此設定選取目標。"],["Target.FOV","Maximum target angle from the view direction.","目标与视角方向之间的最大夹角。","目標與視角方向之間的最大夾角。"],["Target.HurtTime","Highest remaining target hurt time allowed for selection.","允许选择目标的最大剩余受伤时间。","允許選取目標的最大剩餘受傷時間。"],["Target.Priority","Ordered comparators used to select the first valid combat target.","按顺序比较各项条件，选择第一个有效战斗目标。","依序比較各項條件，選取第一個有效戰鬥目標。"],["FollowRange","Maximum feet-to-feet target distance; never lower than Range.","目标与玩家脚部之间的最大距离，不低于环绕范围。","目標與玩家腳部之間的最大距離，不低於環繞範圍。"],["VerticalRange","Maximum target height difference; it must also remain below Range.","允许的最大目标高度差，同时必须小于环绕范围。","允許的最大目標高度差，同時必須小於環繞範圍。"],["Requirements","Every selected requirement must be met before strafing.","开始环绕前，必须满足所有选中的条件。","開始環繞前，必須滿足所有選取的條件。"],["Planner","Configure orbit direction, terrain validation and visibility probing.","配置环绕方向、地形校验和视线探测。","設定環繞方向、地形驗證和視線探測。"],["Planner.Enabled","Parent toggle for the planner settings group.","路径规划设置组的上级开关。","路徑規劃設定群組的上層開關。"],["Planner.ControlDirection","Use left and right movement input to choose the orbit direction.","使用左、右移动输入选择环绕方向。","使用左、右移動輸入選擇環繞方向。"],["Planner.Validation","Always reject colliding positions and optionally validate terrain below them.","始终拒绝发生碰撞的位置，并可检查下方地形。","一律拒絕發生碰撞的位置，並可檢查下方地形。"],["Planner.Validation.Enabled","Enable edge and void validation in addition to collision checks.","在碰撞检查之外，启用边缘与虚空校验。","在碰撞檢查之外，啟用邊緣與虛空驗證。"],["Planner.Validation.EdgeCheck","Reject positions with no support within the configured fall height.","拒绝指定下落高度内没有支撑的位置。","拒絕指定下落高度內沒有支撐的位置。"],["Planner.Validation.EdgeCheck.Enabled","Enable the near-edge fall check.","启用边缘附近的下落检查。","啟用邊緣附近的下落檢查。"],["Planner.Validation.EdgeCheck.MaxFallHeight","Depth of the player-sized collision probe below the next position.","下一位置下方玩家尺寸碰撞探测的深度。","下一位置下方玩家尺寸碰撞探測的深度。"],["Planner.Validation.VoidCheck","Require block support between the next position and Y -64.","要求下一位置到 Y=-64 之间存在方块支撑。","要求下一位置至 Y=-64 之間存在方塊支撐。"],["Planner.Validation.VoidCheck.Enabled","Enable the void support check.","启用虚空支撑检查。","啟用虛空支撐檢查。"],["Planner.Validation.VoidCheck.SafetyExpand","Horizontal expansion of the support search box.","支撑搜索碰撞箱的水平扩展距离。","支撐搜尋碰撞箱的水平擴展距離。"],["Planner.AdaptiveRange","Try smaller orbit radii when the normal next point is unsafe.","普通下一位置不安全时，尝试更小的环绕半径。","一般下一位置不安全時，嘗試較小的環繞半徑。"],["Planner.AdaptiveRange.Enabled","Enable alternate radius probing before reversing direction.","在反转方向前，启用其他半径的探测。","在反轉方向前，啟用其他半徑的探測。"],["Planner.AdaptiveRange.MaxRange","Upper range limit for alternate radius probes.","其他环绕半径探测的范围上限。","其他環繞半徑探測的範圍上限。"],["Planner.AdaptiveRange.RangeStep","Increment between successive alternate radius probes.","相邻环绕半径探测之间的增量。","相鄰環繞半徑探測之間的增量。"],["Planner.Visibility","Keep sight of the target or choose the side that regains sight sooner.","保持目标可见，或选择更快恢复视线的一侧。","保持目標可見，或選擇較快恢復視線的一側。"],["Planner.Visibility.Enabled","Enable target sight checks and path probing.","启用目标视线检查与路径探测。","啟用目標視線檢查與路徑探測。"],["Planner.Visibility.SearchDistance","Distance to search along each side in half-block probes.","沿左右两侧按半格间隔探测的搜索距离。","沿左右兩側以半格間隔探測的搜尋距離。"],["Visuals","Draw the orbit ring and the next planned position.","绘制环绕圆环和规划的下一位置。","繪製環繞圓環和規劃的下一位置。"],["Visuals.Enabled","Show the current orbit plan.","显示当前环绕规划。","顯示目前環繞規劃。"],["Visuals.Width","Thickness of the orbit ring in blocks.","环绕圆环的宽度，单位为格。","環繞圓環的寬度，單位為格。"],["Visuals.HeightOffset","Vertical offset of the ring and position marker.","圆环和位置标记的垂直偏移。","圓環和位置標記的垂直偏移。"],["Visuals.OuterColor","Color and opacity at the outer edge of the ring.","圆环外缘的颜色与不透明度。","圓環外緣的顏色與不透明度。"],["Visuals.InnerColor","Color and opacity at the inner edge of the ring.","圆环内缘的颜色与不透明度。","圓環內緣的顏色與不透明度。"],["Visuals.OutlineColor","Color and opacity of the orbit outline.","环绕轮廓的颜色与不透明度。","環繞輪廓的顏色與不透明度。"],["Visuals.ShowNextPoint","Show the next position chosen by the planner.","显示规划器选择的下一位置。","顯示規劃器選擇的下一位置。"],["Visuals.PointRadius","Radius of the next-position marker.","下一位置标记的半径。","下一位置標記的半徑。"],["Visuals.PointColor","Color of the next point when the plan is safe.","规划安全时下一位置的颜色。","規劃安全時下一位置的顏色。"],["Visuals.PointOutlineColor","Outline color of a safe next point.","安全下一位置的轮廓颜色。","安全下一位置的輪廓顏色。"],["Visuals.InvalidPointColor","Color of the next point when validation fails.","安全校验未通过时下一位置的颜色。","安全驗證未通過時下一位置的顏色。"],["Visuals.InvalidPointOutlineColor","Outline color of an unsafe next point.","危险下一位置的轮廓颜色。","危險下一位置的輪廓顏色。"]]''')
def camel(path):return '.'.join('fov'if n=='FOV'else n[:1].lower()+n[1:]for n in path.split('.'))
def update(folder):
 for code,index in [('zh_cn',1),('zh_tw',2)]:
  path=folder/f'display_{code}.json';data=json.loads(path.read_text(encoding='utf8'));texts={camel(p)+'.description'if p else'description':(en,cn,tw)for p,en,cn,tw in TEXTS}
  put_module(data,PREFIX,'TargetStrafe',{'':('目标环绕','目標環繞')[index-1],**{k:v[index]for k,v in texts.items()}},{k:v[0]for k,v in texts.items()})
  labels=data.setdefault('labels',{})
  for p,*_ in TEXTS:
   if p:labels[PREFIX+'.'+camel(p)]=LABELS[p.rsplit('.',1)[-1]][index-1]
  for p,options in [('mode',['Motion','Input']),('requirements',['Space','Speed','KillAura','Ground']),('target.priority',['Type','Health','Distance','Direction','HurtTime','Age'])]:
   for n in options:labels[PREFIX+'.'+p+'.'+n]=LABELS[n][index-1]
  for k,v in LABELS.items():labels.setdefault(k,v[index-1])
  path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
if __name__=='__main__':
 ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--folder',type=Path,default=HERE.parent/'liquidbounce-interop/resources/localization');update(ap.parse_args().folder)
